17	package com.google.zxing.qrcode.detector;
18	
19	import com.google.zxing.DecodeHintType;
20	import com.google.zxing.NotFoundException;
21	import com.google.zxing.ResultPoint;
22	import com.google.zxing.ResultPointCallback;
23	import com.google.zxing.common.BitMatrix;
24	
25	import java.io.Serializable;
26	import java.util.ArrayList;
27	import java.util.Arrays;
28	import java.util.Collections;
29	import java.util.Comparator;
30	import java.util.Iterator;
31	import java.util.List;
32	import java.util.Map;
33	
34	/**
35	 * <p>This class attempts to find finder patterns in a QR Code. Finder patterns are the square
36	 * markers at three corners of a QR Code.</p>
37	 *
38	 * <p>This class is thread-safe but not reentrant. Each thread must allocate its own object.
39	 *
40	 * @author Sean Owen
41	 */
42	public class FinderPatternFinder {
43	
44	  private static final int CENTER_QUORUM = 2;
45	  private static final int MAX_FINDER_PATTERN_CANDIDATES = 25;
46	  private static final EstimatedModuleComparator moduleComparator = new EstimatedModuleComparator();
47	  protected static final int MIN_SKIP = 3; // 1 pixel/module times 3 modules/center
48	  protected static final int MAX_MODULES = 97; // support up to version 20 for mobile clients
49	
50	  private final BitMatrix image;
51	  private final List<FinderPattern> possibleCenters;
52	  private boolean hasSkipped;
53	  private final int[] crossCheckStateCount;
54	  private final ResultPointCallback resultPointCallback;
55	
56	  /**
57	   * <p>Creates a finder that will search the image for three finder patterns.</p>
58	   *
59	   * @param image image to search
60	   */
61	  public FinderPatternFinder(BitMatrix image) {
62	    this(image, null);
63	  }
64	
65	  public FinderPatternFinder(BitMatrix image, ResultPointCallback resultPointCallback) {
66	    this.image = image;
67	    this.possibleCenters = new ArrayList<>();
68	    this.crossCheckStateCount = new int[5];
69	    this.resultPointCallback = resultPointCallback;
70	  }
71	
72	  protected final BitMatrix getImage() {
73	    return image;
74	  }
75	
76	  protected final List<FinderPattern> getPossibleCenters() {
77	    return possibleCenters;
78	  }
79	
80	  final FinderPatternInfo find(Map<DecodeHintType,?> hints) throws NotFoundException {
81	    boolean tryHarder = hints != null && hints.containsKey(DecodeHintType.TRY_HARDER);
82	    int maxI = image.getHeight();
83	    int maxJ = image.getWidth();
84	    // We are looking for black/white/black/white/black modules in
85	    // 1:1:3:1:1 ratio; this tracks the number of such modules seen so far
86	
87	    // Let's assume that the maximum version QR Code we support takes up 1/4 the height of the
88	    // image, and then account for the center being 3 modules in size. This gives the smallest
89	    // number of pixels the center could be, so skip this often. When trying harder, look for all
90	    // QR versions regardless of how dense they are.
91	    int iSkip = (3 * maxI) / (4 * MAX_MODULES);
92	    if (iSkip < MIN_SKIP || tryHarder) {
93	      iSkip = MIN_SKIP;
94	    }
95	
96	    boolean done = false;
97	    int[] stateCount = new int[5];
98	    for (int i = iSkip - 1; i < maxI && !done; i += iSkip) {
99	      // Get a row of black/white values
100	      doClearCounts(stateCount);
101	      int currentState = 0;
102	      for (int j = 0; j < maxJ; j++) {
103	        if (image.get(j, i)) {
104	          // Black pixel
105	          if ((currentState & 1) == 1) { // Counting white pixels
106	            currentState++;
107	          }
108	          stateCount[currentState]++;
109	        } else { // White pixel
110	          if ((currentState & 1) == 0) { // Counting black pixels
111	            if (currentState == 4) { // A winner?
112	              if (foundPatternCross(stateCount)) { // Yes
113	                boolean confirmed = handlePossibleCenter(stateCount, i, j);
114	                if (confirmed) {
115	                  // Start examining every other line. Checking each line turned out to be too
116	                  // expensive and didn't improve performance.
117	                  iSkip = 2;
118	                  if (hasSkipped) {
119	                    done = haveMultiplyConfirmedCenters();
120	                  } else {
121	                    int rowSkip = findRowSkip();
122	                    if (rowSkip > stateCount[2]) {
123	                      // Skip rows between row of lower confirmed center
124	                      // and top of presumed third confirmed center
125	                      // but back up a bit to get a full chance of detecting
126	                      // it, entire width of center of finder pattern
127	
128	                      // Skip by rowSkip, but back off by stateCount[2] (size of last center
129	                      // of pattern we saw) to be conservative, and also back off by iSkip which
130	                      // is about to be re-added
131	                      i += rowSkip - stateCount[2] - iSkip;
132	                      j = maxJ - 1;
133	                    }
134	                  }
135	                } else {
136	                  doShiftCounts2(stateCount);
137	                  currentState = 3;
138	                  continue;
139	                }
140	                // Clear state to start looking again
141	                currentState = 0;
142	                doClearCounts(stateCount);
143	              } else { // No, shift counts back by two
144	                doShiftCounts2(stateCount);
145	                currentState = 3;
146	              }
147	            } else {
148	              stateCount[++currentState]++;
149	            }
150	          } else { // Counting white pixels
151	            stateCount[currentState]++;
152	          }
153	        }
154	      }
155	      if (foundPatternCross(stateCount)) {
156	        boolean confirmed = handlePossibleCenter(stateCount, i, maxJ);
157	        if (confirmed) {
158	          iSkip = stateCount[0];
159	          if (hasSkipped) {
160	            // Found a third one
161	            done = haveMultiplyConfirmedCenters();
162	          }
163	        }
164	      }
165	    }
166	
167	    FinderPattern[] patternInfo = selectBestPatterns();
168	    ResultPoint.orderBestPatterns(patternInfo);
169	
170	    return new FinderPatternInfo(patternInfo);
171	  }
172	
173	  /**
174	   * Given a count of black/white/black/white/black pixels just seen and an end position,
175	   * figures the location of the center of this run.
176	   */
177	  private static float centerFromEnd(int[] stateCount, int end) {
178	    return (end - stateCount[4] - stateCount[3]) - stateCount[2] / 2.0f;
179	  }
180	
181	  /**
182	   * @param stateCount count of black/white/black/white/black pixels just read
183	   * @return true iff the proportions of the counts is close enough to the 1/1/3/1/1 ratios
184	   *         used by finder patterns to be considered a match
185	   */
186	  protected static boolean foundPatternCross(int[] stateCount) {
187	    return foundPattern(stateCount, 2.0f);
188	  }
189	
190	  /**
191	   * @param stateCount count of black/white/black/white/black pixels just read
192	   * @return true iff the proportions of the counts is close enough to the 1/1/3/1/1 ratios
193	   *         used by finder patterns to be considered a match
194	   */
195	  protected static boolean foundPatternDiagonal(int[] stateCount) {
196	    return foundPattern(stateCount, 1.333f);
197	  }
198	
199	  private static boolean foundPattern(int[] stateCount, float varianceDivisor) {
200	    int totalModuleSize = 0;
201	    for (int i = 0; i < 5; i++) {
202	      int count = stateCount[i];
203	      if (count == 0) {
204	        return false;
205	      }
206	      totalModuleSize += count;
207	    }
208	    if (totalModuleSize < 7) {
209	      return false;
210	    }
211	    float moduleSize = totalModuleSize / 7.0f;
212	    float maxVariance = moduleSize / varianceDivisor;
213	    return
214	        Math.abs(moduleSize - stateCount[0]) < maxVariance &&
215	        Math.abs(moduleSize - stateCount[1]) < maxVariance &&
216	        Math.abs(3.0f * moduleSize - stateCount[2]) < 3 * maxVariance &&
217	        Math.abs(moduleSize - stateCount[3]) < maxVariance &&
218	        Math.abs(moduleSize - stateCount[4]) < maxVariance;
219	  }
220	
221	  private int[] getCrossCheckStateCount() {
222	    doClearCounts(crossCheckStateCount);
223	    return crossCheckStateCount;
224	  }
225	
226	  @Deprecated
227	  protected final void clearCounts(int[] counts) {
228	    doClearCounts(counts);
229	  }
230	
231	  @Deprecated
232	  protected final void shiftCounts2(int[] stateCount) {
233	    doShiftCounts2(stateCount);
234	  }
235	
236	  protected static void doClearCounts(int[] counts) {
237	    Arrays.fill(counts, 0);
238	  }
239	
240	  private static int stateCountTotal(int[] stateCount) {
241	    return stateCount[0] + stateCount[1] + stateCount[2] + stateCount[3] + stateCount[4];
242	  }
243	
244	  protected static void doShiftCounts2(int[] stateCount) {
245	    stateCount[0] = stateCount[2];
246	    stateCount[1] = stateCount[3];
247	    stateCount[2] = stateCount[4];
248	    stateCount[3] = 1;
249	    stateCount[4] = 0;
250	  }
251	
252	  /**
253	   * After a vertical and horizontal scan finds a potential finder pattern, this method
254	   * "cross-cross-cross-checks" by scanning down diagonally through the center of the possible
255	   * finder pattern to see if the same proportion is detected.
256	   *
257	   * @param centerI row where a finder pattern was detected
258	   * @param centerJ center of the section that appears to cross a finder pattern
259	   * @return true if proportions are withing expected limits
260	   */
261	  private boolean crossCheckDiagonal(int centerI, int centerJ) {
262	    int[] stateCount = getCrossCheckStateCount();
263	
264	    // Start counting up, left from center finding black center mass
265	    int i = 0;
266	    while (centerI >= i && centerJ >= i && image.get(centerJ - i, centerI - i)) {
267	      stateCount[2]++;
268	      i++;
269	    }
270	    if (stateCount[2] == 0) {
271	      return false;
272	    }
273	
274	    // Continue up, left finding white space
275	    while (centerI >= i && centerJ >= i && !image.get(centerJ - i, centerI - i)) {
276	      stateCount[1]++;
277	      i++;
278	    }
279	    if (stateCount[1] == 0) {
280	      return false;
281	    }
282	
283	    // Continue up, left finding black border
284	    while (centerI >= i && centerJ >= i && image.get(centerJ - i, centerI - i)) {
285	      stateCount[0]++;
286	      i++;
287	    }
288	    if (stateCount[0] == 0) {
289	      return false;
290	    }
291	
292	    int maxI = image.getHeight();
293	    int maxJ = image.getWidth();
294	
295	    // Now also count down, right from center
296	    i = 1;
297	    while (centerI + i < maxI && centerJ + i < maxJ && image.get(centerJ + i, centerI + i)) {
298	      stateCount[2]++;
299	      i++;
300	    }
301	
302	    while (centerI + i < maxI && centerJ + i < maxJ && !image.get(centerJ + i, centerI + i)) {
303	      stateCount[3]++;
304	      i++;
305	    }
306	    if (stateCount[3] == 0) {
307	      return false;
308	    }
309	
310	    while (centerI + i < maxI && centerJ + i < maxJ && image.get(centerJ + i, centerI + i)) {
311	      stateCount[4]++;
312	      i++;
313	    }
314	    if (stateCount[4] == 0) {
315	      return false;
316	    }
317	
318	    return foundPatternDiagonal(stateCount);
319	  }
320	
321	  /**
322	   * <p>After a horizontal scan finds a potential finder pattern, this method
323	   * "cross-checks" by scanning down vertically through the center of the possible
324	   * finder pattern to see if the same proportion is detected.</p>
325	   *
326	   * @param startI row where a finder pattern was detected
327	   * @param centerJ center of the section that appears to cross a finder pattern
328	   * @param maxCount maximum reasonable number of modules that should be
329	   * observed in any reading state, based on the results of the horizontal scan
330	   * @return vertical center of finder pattern, or {@link Float#NaN} if not found
331	   */
332	  private float crossCheckVertical(int startI, int centerJ, int maxCount,
333	      int originalStateCountTotal) {
334	    BitMatrix image = this.image;
335	
336	    int maxI = image.getHeight();
337	    int[] stateCount = getCrossCheckStateCount();
338	
339	    // Start counting up from center
340	    int i = startI;
341	    while (i >= 0 && image.get(centerJ, i)) {
342	      stateCount[2]++;
343	      i--;
344	    }
345	    if (i < 0) {
346	      return Float.NaN;
347	    }
348	    while (i >= 0 && !image.get(centerJ, i) && stateCount[1] <= maxCount) {
349	      stateCount[1]++;
350	      i--;
351	    }
352	    // If already too many modules in this state or ran off the edge:
353	    if (i < 0 || stateCount[1] > maxCount) {
354	      return Float.NaN;
355	    }
356	    while (i >= 0 && image.get(centerJ, i) && stateCount[0] <= maxCount) {
357	      stateCount[0]++;
358	      i--;
359	    }
360	    if (stateCount[0] > maxCount) {
361	      return Float.NaN;
362	    }
363	
364	    // Now also count down from center
365	    i = startI + 1;
366	    while (i < maxI && image.get(centerJ, i)) {
367	      stateCount[2]++;
368	      i++;
369	    }
370	    if (i == maxI) {
371	      return Float.NaN;
372	    }
373	    while (i < maxI && !image.get(centerJ, i) && stateCount[3] < maxCount) {
374	      stateCount[3]++;
375	      i++;
376	    }
377	    if (i == maxI || stateCount[3] >= maxCount) {
378	      return Float.NaN;
379	    }
380	    while (i < maxI && image.get(centerJ, i) && stateCount[4] < maxCount) {
381	      stateCount[4]++;
382	      i++;
383	    }
384	    if (stateCount[4] >= maxCount) {
385	      return Float.NaN;
386	    }
387	
388	    // If we found a finder-pattern-like section, but its size is more than 40% different than
389	    // the original, assume it's a false positive
390	    int stateCountTotal = stateCountTotal(stateCount);
391	    if (5 * Math.abs(stateCountTotal - originalStateCountTotal) >= 2 * originalStateCountTotal) {
392	      return Float.NaN;
393	    }
394	
395	    return foundPatternCross(stateCount) ? centerFromEnd(stateCount, i) : Float.NaN;
396	  }
397	
398	  /**
399	   * <p>Like {@link #crossCheckVertical(int, int, int, int)}, and in fact is basically identical,
400	   * except it reads horizontally instead of vertically. This is used to cross-cross
401	   * check a vertical cross check and locate the real center of the alignment pattern.</p>
402	   */
403	  private float crossCheckHorizontal(int startJ, int centerI, int maxCount,
404	      int originalStateCountTotal) {
405	    BitMatrix image = this.image;
406	
407	    int maxJ = image.getWidth();
408	    int[] stateCount = getCrossCheckStateCount();
409	
410	    int j = startJ;
411	    while (j >= 0 && image.get(j, centerI)) {
412	      stateCount[2]++;
413	      j--;
414	    }
415	    if (j < 0) {
416	      return Float.NaN;
417	    }
418	    while (j >= 0 && !image.get(j, centerI) && stateCount[1] <= maxCount) {
419	      stateCount[1]++;
420	      j--;
421	    }
422	    if (j < 0 || stateCount[1] > maxCount) {
423	      return Float.NaN;
424	    }
425	    while (j >= 0 && image.get(j, centerI) && stateCount[0] <= maxCount) {
426	      stateCount[0]++;
427	      j--;
428	    }
429	    if (stateCount[0] > maxCount) {
430	      return Float.NaN;
431	    }
432	
433	    j = startJ + 1;
434	    while (j < maxJ && image.get(j, centerI)) {
435	      stateCount[2]++;
436	      j++;
437	    }
438	    if (j == maxJ) {
439	      return Float.NaN;
440	    }
441	    while (j < maxJ && !image.get(j, centerI) && stateCount[3] < maxCount) {
442	      stateCount[3]++;
443	      j++;
444	    }
445	    if (j == maxJ || stateCount[3] >= maxCount) {
446	      return Float.NaN;
447	    }
448	    while (j < maxJ && image.get(j, centerI) && stateCount[4] < maxCount) {
449	      stateCount[4]++;
450	      j++;
451	    }
452	    if (stateCount[4] >= maxCount) {
453	      return Float.NaN;
454	    }
455	
456	    // If we found a finder-pattern-like section, but its size is significantly different than
457	    // the original, assume it's a false positive
458	    int stateCountTotal = stateCountTotal(stateCount);
459	    if (5 * Math.abs(stateCountTotal - originalStateCountTotal) >= originalStateCountTotal) {
460	      return Float.NaN;
461	    }
462	
463	    return foundPatternCross(stateCount) ? centerFromEnd(stateCount, j) : Float.NaN;
464	  }
465	
466	  /**
467	   * @param stateCount reading state module counts from horizontal scan
468	   * @param i row where finder pattern may be found
469	   * @param j end of possible finder pattern in row
470	   * @param pureBarcode ignored
471	   * @return true if a finder pattern candidate was found this time
472	   * @deprecated only exists for backwards compatibility
473	   * @see #handlePossibleCenter(int[], int, int)
474	   */
475	  @Deprecated
476	  protected final boolean handlePossibleCenter(int[] stateCount, int i, int j, boolean pureBarcode) {
477	    return handlePossibleCenter(stateCount, i, j);
478	  }
479	
480	  /**
481	   * <p>This is called when a horizontal scan finds a possible alignment pattern. It will
482	   * cross check with a vertical scan, and if successful, will, ah, cross-cross-check
483	   * with another horizontal scan. This is needed primarily to locate the real horizontal
484	   * center of the pattern in cases of extreme skew.
485	   * And then we cross-cross-cross check with another diagonal scan.</p>
486	   *
487	   * <p>If that succeeds the finder pattern location is added to a list that tracks
488	   * the number of times each location has been nearly-matched as a finder pattern.
489	   * Each additional find is more evidence that the location is in fact a finder
490	   * pattern center
491	   *
492	   * @param stateCount reading state module counts from horizontal scan
493	   * @param i row where finder pattern may be found
494	   * @param j end of possible finder pattern in row
495	   * @return true if a finder pattern candidate was found this time
496	   */
497	  protected final boolean handlePossibleCenter(int[] stateCount, int i, int j) {
498	    int stateCountTotal = stateCountTotal(stateCount);
499	    float centerJ = centerFromEnd(stateCount, j);
500	    float centerI = crossCheckVertical(i, (int) centerJ, stateCount[2], stateCountTotal);
501	    if (!Float.isNaN(centerI)) {
502	      // Re-cross check
503	      centerJ = crossCheckHorizontal((int) centerJ, (int) centerI, stateCount[2], stateCountTotal);
504	      if (!Float.isNaN(centerJ) && crossCheckDiagonal((int) centerI, (int) centerJ)) {
505	        float estimatedModuleSize = stateCountTotal / 7.0f;
506	        boolean found = false;
507	        for (int index = 0; index < possibleCenters.size(); index++) {
508	          FinderPattern center = possibleCenters.get(index);
509	          // Look for about the same center and module size:
510	          if (center.aboutEquals(estimatedModuleSize, centerI, centerJ)) {
511	            possibleCenters.set(index, center.combineEstimate(centerI, centerJ, estimatedModuleSize));
512	            found = true;
513	            break;
514	          }
515	        }
516	        if (!found) {
517	          FinderPattern point = new FinderPattern(centerJ, centerI, estimatedModuleSize);
518	          possibleCenters.add(point);
519	          if (resultPointCallback != null) {
520	            resultPointCallback.foundPossibleResultPoint(point);
521	          }
522	        }
523	        return true;
524	      }
525	    }
526	    return false;
527	  }
528	
529	  /**
530	   * @return number of rows we could safely skip during scanning, based on the first
531	   *         two finder patterns that have been located. In some cases their position will
532	   *         allow us to infer that the third pattern must lie below a certain point farther
533	   *         down in the image.
534	   */
535	  private int findRowSkip() {
536	    int max = possibleCenters.size();
537	    if (max <= 1) {
538	      return 0;
539	    }
540	    ResultPoint firstConfirmedCenter = null;
541	    for (FinderPattern center : possibleCenters) {
542	      if (center.getCount() >= CENTER_QUORUM) {
543	        if (firstConfirmedCenter == null) {
544	          firstConfirmedCenter = center;
545	        } else {
546	          // We have two confirmed centers
547	          // How far down can we skip before resuming looking for the next
548	          // pattern? In the worst case, only the difference between the
549	          // difference in the x / y coordinates of the two centers.
550	          // This is the case where you find top left last.
551	          hasSkipped = true;
552	          return (int) (Math.abs(firstConfirmedCenter.getX() - center.getX()) -
553	              Math.abs(firstConfirmedCenter.getY() - center.getY())) / 2;
554	        }
555	      }
556	    }
557	    return 0;
558	  }
559	
560	  /**
561	   * @return true iff we have found at least 3 finder patterns that have been detected
562	   *         at least {@link #CENTER_QUORUM} times each, and, the estimated module size of the
563	   *         candidates is "pretty similar"
564	   */
565	  private boolean haveMultiplyConfirmedCenters() {
566	    int confirmedCount = 0;
567	    float totalModuleSize = 0.0f;
568	    int max = possibleCenters.size();
569	    for (FinderPattern pattern : possibleCenters) {
570	      if (pattern.getCount() >= CENTER_QUORUM) {
571	        confirmedCount++;
572	        totalModuleSize += pattern.getEstimatedModuleSize();
573	      }
574	    }
575	    if (confirmedCount < 3) {
576	      return false;
577	    }
578	    // OK, we have at least 3 confirmed centers, but, it's possible that one is a "false positive"
579	    // and that we need to keep looking. We detect this by asking if the estimated module sizes
580	    // vary too much. We arbitrarily say that when the total deviation from average exceeds
581	    // 5% of the total module size estimates, it's too much.
582	    float average = totalModuleSize / max;
583	    float totalDeviation = 0.0f;
584	    for (FinderPattern pattern : possibleCenters) {
585	      totalDeviation += Math.abs(pattern.getEstimatedModuleSize() - average);
586	    }
587	    return totalDeviation <= 0.05f * totalModuleSize;
588	  }
589	
590	  /**
591	   * Get square of distance between a and b.
592	   */
593	  private static double squaredDistance(FinderPattern a, FinderPattern b) {
594	    double x = a.getX() - b.getX();
595	    double y = a.getY() - b.getY();
596	    return x * x + y * y;
597	  }
598	
599	  /**
600	   * @return the 3 best {@link FinderPattern}s from our list of candidates. The "best" are
601	   *         those have similar module size and form a shape closer to a isosceles right triangle.
602	   * @throws NotFoundException if 3 such finder patterns do not exist
603	   */
604	  private FinderPattern[] selectBestPatterns() throws NotFoundException {
605	
606	    int startSize = possibleCenters.size();
607	    if (startSize < 3) {
608	      // Couldn't find enough finder patterns
609	      throw NotFoundException.getNotFoundInstance();
610	    }
611	
612	    int confirmedCount = 0;
613	    for (FinderPattern pattern : possibleCenters) {
614	      if (pattern.getCount() >= CENTER_QUORUM) {
615	        confirmedCount++;
616	      }
617	    }
618	    if (confirmedCount >= 3 || startSize > MAX_FINDER_PATTERN_CANDIDATES) {
619	      for (Iterator<FinderPattern> it = possibleCenters.iterator(); it.hasNext();) {
620	        if (it.next().getCount() < CENTER_QUORUM) {
621	          it.remove();
622	        }
623	      }
624	    }
625	
626	    // A more up-to-date version would be "possibleCenters.sort(moduleComparator);"
627	    // But we need this old syntax for android API 23 (Marshmallow) and below
628	    // cf. https://github.com/zxing/zxing/issues/1358
629	    Collections.sort(possibleCenters, moduleComparator);
630	
631	    double distortion = Double.MAX_VALUE;
632	    FinderPattern[] bestPatterns = new FinderPattern[3];
633	
634	    for (int i = 0; i < possibleCenters.size() - 2; i++) {
635	      FinderPattern fpi = possibleCenters.get(i);
636	      float minModuleSize = fpi.getEstimatedModuleSize();
637	
638	      for (int j = i + 1; j < possibleCenters.size() - 1; j++) {
639	        FinderPattern fpj = possibleCenters.get(j);
640	        double squares0 = squaredDistance(fpi, fpj);
641	
642	        for (int k = j + 1; k < possibleCenters.size(); k++) {
643	          FinderPattern fpk = possibleCenters.get(k);
644	          float maxModuleSize = fpk.getEstimatedModuleSize();
645	          if (maxModuleSize > minModuleSize * 1.4f) {
646	            // module size is not similar
647	            continue;
648	          }
649	
650	          double a = squares0;
651	          double b = squaredDistance(fpj, fpk);
652	          double c = squaredDistance(fpi, fpk);
653	
654	          double[] sides = {a, b, c};
655	          Arrays.sort(sides);
656	          a = sides[0];
657	          b = sides[1];
658	          c = sides[2];
659	
660	          // a^2 + b^2 = c^2 (Pythagorean theorem), and a = b (isosceles triangle).
661	          // Since any right triangle satisfies the formula c^2 - b^2 - a^2 = 0,
662	          // we need to check both two equal sides separately.
663	          // The value of |c^2 - 2 * b^2| + |c^2 - 2 * a^2| increases as dissimilarity
664	          // from isosceles right triangle.
665	          // Heuristically it seems that the following formula works better (although it's
666	          // not clear any more why...)
667	          double d = Math.abs(c - 2 * b) + Math.abs(c - 2 * a);
668	          if (d < distortion) {
669	            distortion = d;
670	            bestPatterns[0] = fpi;
671	            bestPatterns[1] = fpj;
672	            bestPatterns[2] = fpk;
673	          }
674	        }
675	      }
676	    }
677	
678	    if (distortion == Double.MAX_VALUE) {
679	      throw NotFoundException.getNotFoundInstance();
680	    }
681	
682	    return bestPatterns;
683	  }
684	
685	  /**
686	   * <p>Orders by {@link FinderPattern#getEstimatedModuleSize()}</p>
687	   */
688	  private static final class EstimatedModuleComparator implements Comparator<FinderPattern>, Serializable {
689	    @Override
690	    public int compare(FinderPattern center1, FinderPattern center2) {
691	      return Float.compare(center1.getEstimatedModuleSize(), center2.getEstimatedModuleSize());
692	    }
693	  }
694	
695	}
