17	package com.google.zxing.common;
18	
19	import com.google.zxing.FormatException;
20	
21	import java.nio.charset.Charset;
22	import java.nio.charset.StandardCharsets;
23	import java.util.HashMap;
24	import java.util.Map;
25	
26	/**
27	 * Encapsulates a Character Set ECI, according to "Extended Channel Interpretations" 5.3.1.1
28	 * of ISO 18004.
29	 *
30	 * @author Sean Owen
31	 */
32	public enum CharacterSetECI {
33	
34	  // Enum name is a Java encoding valid for java.lang and java.io
35	  Cp437(new int[]{0,2}),
36	  ISO8859_1(new int[]{1,3}, StandardCharsets.ISO_8859_1, "ISO-8859-1"),
37	  ISO8859_2(4, "ISO-8859-2"),
38	  ISO8859_3(5, "ISO-8859-3"),
39	  ISO8859_4(6, "ISO-8859-4"),
40	  ISO8859_5(7, "ISO-8859-5"),
41	  ISO8859_6(8, "ISO-8859-6"),
42	  ISO8859_7(9, "ISO-8859-7"),
43	  ISO8859_8(10, "ISO-8859-8"),
44	  ISO8859_9(11, "ISO-8859-9"),
45	  ISO8859_10(12, "ISO-8859-10"),
46	  ISO8859_11(13, "ISO-8859-11"),
47	  ISO8859_13(15, "ISO-8859-13"),
48	  ISO8859_14(16, "ISO-8859-14"),
49	  ISO8859_15(17, "ISO-8859-15"),
50	  ISO8859_16(18, "ISO-8859-16"),
51	  SJIS(20, "Shift_JIS"),
52	  Cp1250(21, "windows-1250"),
53	  Cp1251(22, "windows-1251"),
54	  Cp1252(23, "windows-1252"),
55	  Cp1256(24, "windows-1256"),
56	  UnicodeBigUnmarked(25, StandardCharsets.UTF_16BE, "UTF-16BE", "UnicodeBig"),
57	  UTF8(26, StandardCharsets.UTF_8, "UTF-8"),
58	  ASCII(new int[] {27, 170}, StandardCharsets.US_ASCII, "US-ASCII"),
59	  Big5(28),
60	  GB18030(29, "GB2312", "EUC_CN", "GBK"),
61	  EUC_KR(30, "EUC-KR");
62	
63	  private static final Map<Integer,CharacterSetECI> VALUE_TO_ECI = new HashMap<>();
64	  private static final Map<String,CharacterSetECI> NAME_TO_ECI = new HashMap<>();
65	  static {
66	    for (CharacterSetECI eci : values()) {
67	      for (int value : eci.values) {
68	        VALUE_TO_ECI.put(value, eci);
69	      }
70	      NAME_TO_ECI.put(eci.name(), eci);
71	      for (String name : eci.otherEncodingNames) {
72	        NAME_TO_ECI.put(name, eci);
73	      }
74	    }
75	  }
76	
77	  private final int[] values;
78	  private final Charset standardCharset;
79	  private final String[] otherEncodingNames;
80	
81	  CharacterSetECI(int value) {
82	    this(new int[] {value});
83	  }
84	
85	  CharacterSetECI(int value, String... otherEncodingNames) {
86	    this(new int[] {value}, null, otherEncodingNames);
87	  }
88	
89	  CharacterSetECI(int value, Charset standardCharset, String... otherEncodingNames) {
90	    this(new int[] {value}, standardCharset, otherEncodingNames);
91	  }
92	
93	  CharacterSetECI(int[] values, String... otherEncodingNames) {
94	    this(values, null, otherEncodingNames);
95	  }
96	
97	  CharacterSetECI(int[] values, Charset standardCharset, String... otherEncodingNames) {
98	    this.values = values;
99	    this.standardCharset = standardCharset;
100	    this.otherEncodingNames = otherEncodingNames;
101	  }
102	
103	  public int getValue() {
104	    return values[0];
105	  }
106	
107	  public Charset getCharset() {
108	    if (standardCharset != null) {
109	      return standardCharset;
110	    }
111	    return Charset.forName(name());
112	  }
113	
114	  private boolean isCharsetSupported() {
115	    return standardCharset != null || Charset.isSupported(name());
116	  }
117	
118	  /**
119	   * @param charset Java character set object
120	   * @return CharacterSetECI representing ECI for character encoding, or null if it is legal
121	   *   but unsupported
122	   */
123	  public static CharacterSetECI getCharacterSetECI(Charset charset) {
124	    CharacterSetECI eci = NAME_TO_ECI.get(charset.name());
125	    return eci == null || eci.isCharsetSupported() ? eci : null;
126	  }
127	
128	  /**
129	   * @param value character set ECI value
130	   * @return {@code CharacterSetECI} representing ECI of given value, or null if it is legal but
131	   *   unsupported
132	   * @throws FormatException if ECI value is invalid
133	   */
134	  public static CharacterSetECI getCharacterSetECIByValue(int value) throws FormatException {
135	    if (value < 0 || value >= 900) {
136	      throw FormatException.getFormatInstance();
137	    }
138	    CharacterSetECI eci = VALUE_TO_ECI.get(value);
139	    return eci == null || eci.isCharsetSupported() ? eci : null;
140	  }
141	
142	  /**
143	   * @param name character set ECI encoding name
144	   * @return CharacterSetECI representing ECI for character encoding, or null if it is legal
145	   *   but unsupported
146	   */
147	  public static CharacterSetECI getCharacterSetECIByName(String name) {
148	    CharacterSetECI eci = NAME_TO_ECI.get(name);
149	    return eci == null || eci.isCharsetSupported() ? eci : null;
150	  }
151	
152	}
