32	/**
33	 * This produces nearly optimal encodings of text into the first-level of
34	 * encoding used by Aztec code.
35	 *
36	 * It uses a dynamic algorithm.  For each prefix of the string, it determines
37	 * a set of encodings that could lead to this prefix.  We repeatedly add a
38	 * character and generate a new set of optimal encodings until we have read
39	 * through the entire input.
40	 *
41	 * @author Frank Yellin
42	 * @author Rustam Abdullaev
43	 */
44	public final class HighLevelEncoder {
45	
46	  static final String[] MODE_NAMES = {"UPPER", "LOWER", "DIGIT", "MIXED", "PUNCT"};
47	
48	  static final int MODE_UPPER = 0; // 5 bits
49	  static final int MODE_LOWER = 1; // 5 bits
50	  static final int MODE_DIGIT = 2; // 4 bits
51	  static final int MODE_MIXED = 3; // 5 bits
52	  static final int MODE_PUNCT = 4; // 5 bits
53	
54	  // The Latch Table shows, for each pair of Modes, the optimal method for
55	  // getting from one mode to another.  In the worst possible case, this can
56	  // be up to 14 bits.  In the best possible case, we are already there!
57	  // The high half-word of each entry gives the number of bits.
58	  // The low half-word of each entry are the actual bits necessary to change
59	  static final int[][] LATCH_TABLE = {
60	    {
61	      0,
62	      (5 << 16) + 28,              // UPPER -> LOWER
63	      (5 << 16) + 30,              // UPPER -> DIGIT
64	      (5 << 16) + 29,              // UPPER -> MIXED
65	      (10 << 16) + (29 << 5) + 30, // UPPER -> MIXED -> PUNCT
66	    },
67	    {
68	      (9 << 16) + (30 << 4) + 14,  // LOWER -> DIGIT -> UPPER
69	      0,
70	      (5 << 16) + 30,              // LOWER -> DIGIT
71	      (5 << 16) + 29,              // LOWER -> MIXED
72	      (10 << 16) + (29 << 5) + 30, // LOWER -> MIXED -> PUNCT
73	    },
74	    {
75	      (4 << 16) + 14,              // DIGIT -> UPPER
76	      (9 << 16) + (14 << 5) + 28,  // DIGIT -> UPPER -> LOWER
77	      0,
78	      (9 << 16) + (14 << 5) + 29,  // DIGIT -> UPPER -> MIXED
79	      (14 << 16) + (14 << 10) + (29 << 5) + 30,
80	                                   // DIGIT -> UPPER -> MIXED -> PUNCT
81	    },
82	    {
83	      (5 << 16) + 29,              // MIXED -> UPPER
84	      (5 << 16) + 28,              // MIXED -> LOWER
85	      (10 << 16) + (29 << 5) + 30, // MIXED -> UPPER -> DIGIT
86	      0,
87	      (5 << 16) + 30,              // MIXED -> PUNCT
88	    },
89	    {
90	      (5 << 16) + 31,              // PUNCT -> UPPER
91	      (10 << 16) + (31 << 5) + 28, // PUNCT -> UPPER -> LOWER
92	      (10 << 16) + (31 << 5) + 30, // PUNCT -> UPPER -> DIGIT
93	      (10 << 16) + (31 << 5) + 29, // PUNCT -> UPPER -> MIXED
94	      0,
95	    },
96	  };
97	
98	  // A reverse mapping from [mode][char] to the encoding for that character
99	  // in that mode.  An entry of 0 indicates no mapping exists.
100	  private static final int[][] CHAR_MAP = new int[5][256];
101	  static {
102	    CHAR_MAP[MODE_UPPER][' '] = 1;
103	    for (int c = 'A'; c <= 'Z'; c++) {
104	      CHAR_MAP[MODE_UPPER][c] = c - 'A' + 2;
105	    }
106	    CHAR_MAP[MODE_LOWER][' '] = 1;
107	    for (int c = 'a'; c <= 'z'; c++) {
108	      CHAR_MAP[MODE_LOWER][c] = c - 'a' + 2;
109	    }
110	    CHAR_MAP[MODE_DIGIT][' '] = 1;
111	    for (int c = '0'; c <= '9'; c++) {
112	      CHAR_MAP[MODE_DIGIT][c] = c - '0' + 2;
113	    }
114	    CHAR_MAP[MODE_DIGIT][','] = 12;
115	    CHAR_MAP[MODE_DIGIT]['.'] = 13;
116	    int[] mixedTable = {
117	        '\0', ' ', '\1', '\2', '\3', '\4', '\5', '\6', '\7', '\b', '\t', '\n',
118	        '\13', '\f', '\r', '\33', '\34', '\35', '\36', '\37', '@', '\\', '^',
119	        '_', '`', '|', '~', '\177'
120	    };
121	    for (int i = 0; i < mixedTable.length; i++) {
122	      CHAR_MAP[MODE_MIXED][mixedTable[i]] = i;
123	    }
124	    int[] punctTable = {
125	        '\0', '\r', '\0', '\0', '\0', '\0', '!', '\'', '#', '$', '%', '&', '\'',
126	        '(', ')', '*', '+', ',', '-', '.', '/', ':', ';', '<', '=', '>', '?',
127	        '[', ']', '{', '}'
128	    };
129	    for (int i = 0; i < punctTable.length; i++) {
130	      if (punctTable[i] > 0) {
131	        CHAR_MAP[MODE_PUNCT][punctTable[i]] = i;
132	      }
133	    }
134	  }
135	
136	  // A map showing the available shift codes.  (The shifts to BINARY are not
137	  // shown
138	  static final int[][] SHIFT_TABLE = new int[6][6]; // mode shift codes, per table
139	  static {
140	    for (int[] table : SHIFT_TABLE) {
141	      Arrays.fill(table, -1);
142	    }
143	    SHIFT_TABLE[MODE_UPPER][MODE_PUNCT] = 0;
144	
145	    SHIFT_TABLE[MODE_LOWER][MODE_PUNCT] = 0;
146	    SHIFT_TABLE[MODE_LOWER][MODE_UPPER] = 28;
147	
148	    SHIFT_TABLE[MODE_MIXED][MODE_PUNCT] = 0;
149	
150	    SHIFT_TABLE[MODE_DIGIT][MODE_PUNCT] = 0;
151	    SHIFT_TABLE[MODE_DIGIT][MODE_UPPER] = 15;
152	  }
153	
154	  private final byte[] text;
155	  private final Charset charset;
156	
157	  public HighLevelEncoder(byte[] text) {
158	    this.text = text;
159	    this.charset = null;
160	  }
161	
162	  public HighLevelEncoder(byte[] text, Charset charset) {
163	    this.text = text;
164	    this.charset = charset;
165	  }
166	
167	  /**
168	   * @return text represented by this encoder encoded as a {@link BitArray}
169	   */
170	  public BitArray encode() {
171	    State initialState = State.INITIAL_STATE;
172	    if (charset != null) {
173	      CharacterSetECI eci = CharacterSetECI.getCharacterSetECI(charset);
174	      if (null == eci) {
175	        throw new IllegalArgumentException("No ECI code for character set " + charset);
176	      }
177	      initialState = initialState.appendFLGn(eci.getValue());
178	    }
179	    Collection<State> states = Collections.singletonList(initialState);
180	    for (int index = 0; index < text.length; index++) {
181	      int pairCode;
182	      int nextChar = index + 1 < text.length ? text[index + 1] : 0;
183	      switch (text[index]) {
184	        case '\r':
185	          pairCode = nextChar == '\n' ? 2 : 0;
186	          break;
187	        case '.' :
188	          pairCode = nextChar == ' ' ? 3 : 0;
189	          break;
190	        case ',' :
191	          pairCode = nextChar == ' ' ? 4 : 0;
192	          break;
193	        case ':' :
194	          pairCode = nextChar == ' ' ? 5 : 0;
195	          break;
196	        default:
197	          pairCode = 0;
198	      }
199	      if (pairCode > 0) {
200	        // We have one of the four special PUNCT pairs.  Treat them specially.
201	        // Get a new set of states for the two new characters.
202	        states = updateStateListForPair(states, index, pairCode);
203	        index++;
204	      } else {
205	        // Get a new set of states for the new character.
206	        states = updateStateListForChar(states, index);
207	      }
208	    }
209	    // We are left with a set of states.  Find the shortest one.
210	    State minState = Collections.min(states, new Comparator<State>() {
211	      @Override
212	      public int compare(State a, State b) {
213	        return a.getBitCount() - b.getBitCount();
214	      }
215	    });
216	    // Convert it to a bit array, and return.
217	    return minState.toBitArray(text);
218	  }
219	
220	  // We update a set of states for a new character by updating each state
221	  // for the new character, merging the results, and then removing the
222	  // non-optimal states.
223	  private Collection<State> updateStateListForChar(Iterable<State> states, int index) {
224	    Collection<State> result = new LinkedList<>();
225	    for (State state : states) {
226	      updateStateForChar(state, index, result);
227	    }
228	    return simplifyStates(result);
229	  }
230	
231	  // Return a set of states that represent the possible ways of updating this
232	  // state for the next character.  The resulting set of states are added to
233	  // the "result" list.
234	  private void updateStateForChar(State state, int index, Collection<State> result) {
235	    char ch = (char) (text[index] & 0xFF);
236	    boolean charInCurrentTable = CHAR_MAP[state.getMode()][ch] > 0;
237	    State stateNoBinary = null;
238	    for (int mode = 0; mode <= MODE_PUNCT; mode++) {
239	      int charInMode = CHAR_MAP[mode][ch];
240	      if (charInMode > 0) {
241	        if (stateNoBinary == null) {
242	          // Only create stateNoBinary the first time it's required.
243	          stateNoBinary = state.endBinaryShift(index);
244	        }
245	        // Try generating the character by latching to its mode
246	        if (!charInCurrentTable || mode == state.getMode() || mode == MODE_DIGIT) {
247	          // If the character is in the current table, we don't want to latch to
248	          // any other mode except possibly digit (which uses only 4 bits).  Any
249	          // other latch would be equally successful *after* this character, and
250	          // so wouldn't save any bits.
251	          State latchState = stateNoBinary.latchAndAppend(mode, charInMode);
252	          result.add(latchState);
253	        }
254	        // Try generating the character by switching to its mode.
255	        if (!charInCurrentTable && SHIFT_TABLE[state.getMode()][mode] >= 0) {
256	          // It never makes sense to temporarily shift to another mode if the
257	          // character exists in the current mode.  That can never save bits.
258	          State shiftState = stateNoBinary.shiftAndAppend(mode, charInMode);
259	          result.add(shiftState);
260	        }
261	      }
262	    }
263	    if (state.getBinaryShiftByteCount() > 0 || CHAR_MAP[state.getMode()][ch] == 0) {
264	      // It's never worthwhile to go into binary shift mode if you're not already
265	      // in binary shift mode, and the character exists in your current mode.
266	      // That can never save bits over just outputting the char in the current mode.
267	      State binaryState = state.addBinaryShiftChar(index);
268	      result.add(binaryState);
269	    }
270	  }
271	
272	  private static Collection<State> updateStateListForPair(Iterable<State> states, int index, int pairCode) {
273	    Collection<State> result = new LinkedList<>();
274	    for (State state : states) {
275	      updateStateForPair(state, index, pairCode, result);
276	    }
277	    return simplifyStates(result);
278	  }
279	
280	  private static void updateStateForPair(State state, int index, int pairCode, Collection<State> result) {
281	    State stateNoBinary = state.endBinaryShift(index);
282	    // Possibility 1.  Latch to MODE_PUNCT, and then append this code
283	    result.add(stateNoBinary.latchAndAppend(MODE_PUNCT, pairCode));
284	    if (state.getMode() != MODE_PUNCT) {
285	      // Possibility 2.  Shift to MODE_PUNCT, and then append this code.
286	      // Every state except MODE_PUNCT (handled above) can shift
287	      result.add(stateNoBinary.shiftAndAppend(MODE_PUNCT, pairCode));
288	    }
289	    if (pairCode == 3 || pairCode == 4) {
290	      // both characters are in DIGITS.  Sometimes better to just add two digits
291	      State digitState = stateNoBinary
292	          .latchAndAppend(MODE_DIGIT, 16 - pairCode)  // period or comma in DIGIT
293	          .latchAndAppend(MODE_DIGIT, 1);             // space in DIGIT
294	      result.add(digitState);
295	    }
296	    if (state.getBinaryShiftByteCount() > 0) {
297	      // It only makes sense to do the characters as binary if we're already
298	      // in binary mode.
299	      State binaryState = state.addBinaryShiftChar(index).addBinaryShiftChar(index + 1);
300	      result.add(binaryState);
301	    }
302	  }
303	
304	  private static Collection<State> simplifyStates(Iterable<State> states) {
305	    Deque<State> result = new LinkedList<>();
306	    for (State newState : states) {
307	      boolean add = true;
308	      for (Iterator<State> iterator = result.iterator(); iterator.hasNext();) {
309	        State oldState = iterator.next();
310	        if (oldState.isBetterThanOrEqualTo(newState)) {
311	          add = false;
312	          break;
313	        }
314	        if (newState.isBetterThanOrEqualTo(oldState)) {
315	          iterator.remove();
316	        }
317	      }
318	      if (add) {
319	        result.addFirst(newState);
320	      }
321	    }
322	    return result;
323	  }
324	
