71	    Pair leftPair = decodePair(row, false, rowNumber, hints);
72	    addOrTally(possibleLeftPairs, leftPair);
73	    row.reverse();
74	    Pair rightPair = decodePair(row, true, rowNumber, hints);
75	    addOrTally(possibleRightPairs, rightPair);
76	    row.reverse();
77	    for (Pair left : possibleLeftPairs) {
78	      if (left.getCount() > 1) {
79	        for (Pair right : possibleRightPairs) {
80	          if (right.getCount() > 1 && checkChecksum(left, right)) {

80	          if (right.getCount() > 1 && checkChecksum(left, right)) {
81	            return constructResult(left, right);
