144	  private static boolean checkChecksum(Pair leftPair, Pair rightPair) {
145	    int checkValue = (leftPair.getChecksumPortion() + 16 * rightPair.getChecksumPortion()) % 79;
146	    int targetCheckValue =
147	        9 * leftPair.getFinderPattern().getValue() + rightPair.getFinderPattern().getValue();
148	    if (targetCheckValue > 72) {
149	      targetCheckValue--;
150	    }
151	    if (targetCheckValue > 8) {
152	      targetCheckValue--;
153	    }
154	    return checkValue == targetCheckValue;
155	  }
