157	  private Pair decodePair(BitArray row, boolean right, int rowNumber, Map<DecodeHintType,?> hints) {
158	    try {
159	      int[] startEnd = findFinderPattern(row, right);
160	      FinderPattern pattern = parseFoundFinderPattern(row, rowNumber, right, startEnd);
161	
162	      ResultPointCallback resultPointCallback = hints == null ? null :
163	          (ResultPointCallback) hints.get(DecodeHintType.NEED_RESULT_POINT_CALLBACK);
164	
165	      if (resultPointCallback != null) {
166	        startEnd = pattern.getStartEnd();
167	        float center = (startEnd[0] + startEnd[1] - 1) / 2.0f;
168	        if (right) {
169	          // row is actually reversed
170	          center = row.getSize() - 1 - center;
171	        }
172	        resultPointCallback.foundPossibleResultPoint(new ResultPoint(center, rowNumber));
173	      }
174	
175	      DataCharacter outside = decodeDataCharacter(row, pattern, true);
176	      DataCharacter inside = decodeDataCharacter(row, pattern, false);
177	      return new Pair(1597 * outside.getValue() + inside.getValue(),
178	                      outside.getChecksumPortion() + 4 * inside.getChecksumPortion(),
179	                      pattern);
180	    } catch (NotFoundException ignored) {
181	      return null;
182	    }
183	  }
