185	  private DataCharacter decodeDataCharacter(BitArray row, FinderPattern pattern, boolean outsideChar)
186	      throws NotFoundException {
187	
188	    int[] counters = getDataCharacterCounters();
189	    Arrays.fill(counters, 0);
190	
191	    if (outsideChar) {
192	      recordPatternInReverse(row, pattern.getStartEnd()[0], counters);
193	    } else {
194	      recordPattern(row, pattern.getStartEnd()[1], counters);
195	      // reverse it
196	      for (int i = 0, j = counters.length - 1; i < j; i++, j--) {
197	        int temp = counters[i];
198	        counters[i] = counters[j];
199	        counters[j] = temp;
200	      }
201	    }
202	
203	    int numModules = outsideChar ? 16 : 15;
204	    float elementWidth = MathUtils.sum(counters) / (float) numModules;
205	
206	    int[] oddCounts = this.getOddCounts();
207	    int[] evenCounts = this.getEvenCounts();
208	    float[] oddRoundingErrors = this.getOddRoundingErrors();
209	    float[] evenRoundingErrors = this.getEvenRoundingErrors();
210	
211	    for (int i = 0; i < counters.length; i++) {
212	      float value = counters[i] / elementWidth;
213	      int count = (int) (value + 0.5f); // Round
214	      if (count < 1) {
215	        count = 1;
216	      } else if (count > 8) {
217	        count = 8;
218	      }
219	      int offset = i / 2;
220	      if ((i & 0x01) == 0) {
221	        oddCounts[offset] = count;
222	        oddRoundingErrors[offset] = value - count;
223	      } else {
224	        evenCounts[offset] = count;
225	        evenRoundingErrors[offset] = value - count;
226	      }
227	    }
228	
229	    adjustOddEvenCounts(outsideChar, numModules);
230	
231	    int oddSum = 0;
232	    int oddChecksumPortion = 0;
233	    for (int i = oddCounts.length - 1; i >= 0; i--) {
234	      oddChecksumPortion *= 9;
235	      oddChecksumPortion += oddCounts[i];
236	      oddSum += oddCounts[i];
237	    }
238	    int evenChecksumPortion = 0;
239	    int evenSum = 0;
240	    for (int i = evenCounts.length - 1; i >= 0; i--) {
241	      evenChecksumPortion *= 9;
242	      evenChecksumPortion += evenCounts[i];
243	      evenSum += evenCounts[i];
244	    }
245	    int checksumPortion = oddChecksumPortion + 3 * evenChecksumPortion;
246	
247	    if (outsideChar) {
248	      if ((oddSum & 0x01) != 0 || oddSum > 12 || oddSum < 4) {
249	        throw NotFoundException.getNotFoundInstance();
250	      }
251	      int group = (12 - oddSum) / 2;
252	      int oddWidest = OUTSIDE_ODD_WIDEST[group];
253	      int evenWidest = 9 - oddWidest;
254	      int vOdd = RSSUtils.getRSSvalue(oddCounts, oddWidest, false);
255	      int vEven = RSSUtils.getRSSvalue(evenCounts, evenWidest, true);
256	      int tEven = OUTSIDE_EVEN_TOTAL_SUBSET[group];
257	      int gSum = OUTSIDE_GSUM[group];
258	      return new DataCharacter(vOdd * tEven + vEven + gSum, checksumPortion);
259	    } else {
260	      if ((evenSum & 0x01) != 0 || evenSum > 10 || evenSum < 4) {
261	        throw NotFoundException.getNotFoundInstance();
262	      }
263	      int group = (10 - evenSum) / 2;
264	      int oddWidest = INSIDE_ODD_WIDEST[group];
265	      int evenWidest = 9 - oddWidest;
266	      int vOdd = RSSUtils.getRSSvalue(oddCounts, oddWidest, true);
267	      int vEven = RSSUtils.getRSSvalue(evenCounts, evenWidest, false);
268	      int tOdd = INSIDE_ODD_TOTAL_SUBSET[group];
269	      int gSum = INSIDE_GSUM[group];
270	      return new DataCharacter(vEven * tOdd + vOdd + gSum, checksumPortion);
271	    }
272	
