320	  private FinderPattern parseFoundFinderPattern(BitArray row, int rowNumber, boolean right, int[] startEnd)
321	      throws NotFoundException {
322	    // Actually we found elements 2-5
323	    boolean firstIsBlack = row.get(startEnd[0]);
324	    int firstElementStart = startEnd[0] - 1;
325	    // Locate element 1
326	    while (firstElementStart >= 0 && firstIsBlack != row.get(firstElementStart)) {
327	      firstElementStart--;
328	    }
329	    firstElementStart++;
330	    int firstCounter = startEnd[0] - firstElementStart;
331	    // Make 'counters' hold 1-4
332	    int[] counters = getDecodeFinderCounters();
333	    System.arraycopy(counters, 0, counters, 1, counters.length - 1);
334	    counters[0] = firstCounter;
335	    int value = parseFinderValue(counters, FINDER_PATTERNS);
336	    int start = firstElementStart;
