238	  /**
239	   * <p>Sets a square region of the bit matrix to true.</p>
240	   *
241	   * @param left The horizontal position to begin at (inclusive)
242	   * @param top The vertical position to begin at (inclusive)
243	   * @param width The width of the region
244	   * @param height The height of the region
245	   */
246	  public void setRegion(int left, int top, int width, int height) {
247	    if (top < 0 || left < 0) {
248	      throw new IllegalArgumentException("Left and top must be nonnegative");
249	    }
250	    if (height < 1 || width < 1) {
251	      throw new IllegalArgumentException("Height and width must be at least 1");
252	    }
253	    int right = left + width;
254	    int bottom = top + height;
255	    if (bottom > this.height || right > this.width) {
256	      throw new IllegalArgumentException("The region must fit inside the matrix");
257	    }
258	    for (int y = top; y < bottom; y++) {
259	      int offset = y * rowSize;
260	      for (int x = left; x < right; x++) {
261	        bits[offset + (x / 32)] |= 1 << (x & 0x1f);
262	      }
263	    }
264	  }
