266	  /**
267	   * A fast method to retrieve one row of data from the matrix as a BitArray.
268	   *
269	   * @param y The row to retrieve
270	   * @param row An optional caller-allocated BitArray, will be allocated if null or too small
271	   * @return The resulting BitArray - this reference should always be used even when passing
272	   *         your own row
273	   */
274	  public BitArray getRow(int y, BitArray row) {
275	    if (row == null || row.getSize() < width) {
276	      row = new BitArray(width);
277	    } else {
278	      row.clear();
279	    }
280	    int offset = y * rowSize;
281	    for (int x = 0; x < rowSize; x++) {
282	      row.setBulk(x * 32, bits[offset + x]);
283	    }
284	    return row;
285	  }
