295	  /**
296	   * Modifies this {@code BitMatrix} to represent the same but rotated the given degrees (0, 90, 180, 270)
297	   *
298	   * @param degrees number of degrees to rotate through counter-clockwise (0, 90, 180, 270)
299	   */

295	  /**
296	   * Modifies this {@code BitMatrix} to represent the same but rotated the given degrees (0, 90, 180, 270)
297	   *
298	   * @param degrees number of degrees to rotate through counter-clockwise (0, 90, 180, 270)
299	   */
300	  public void rotate(int degrees) {
301	    switch (degrees % 360) {
302	      case 0:
303	        return;
304	      case 90:
305	        rotate90();
306	        return;
307	      case 180:
308	        rotate180();
309	        return;
310	      case 270:
311	        rotate90();
312	        rotate180();
313	        return;
314	    }
315	    throw new IllegalArgumentException("degrees must be a multiple of 0, 90, 180, or 270");
316	  }
