318	  /**
319	   * Modifies this {@code BitMatrix} to represent the same but rotated 180 degrees
320	   */
321	  public void rotate180() {
322	    BitArray topRow = new BitArray(width);
323	    BitArray bottomRow = new BitArray(width);
324	    int maxHeight = (height + 1) / 2;
325	    for (int i = 0; i < maxHeight; i++) {
326	      topRow = getRow(i, topRow);
327	      int bottomRowIndex = height - 1 - i;
328	      bottomRow = getRow(bottomRowIndex, bottomRow);
329	      topRow.reverse();
330	      bottomRow.reverse();
331	      setRow(i, bottomRow);
332	      setRow(bottomRowIndex, topRow);
333	    }
334	  }
335	
336	  /**
337	   * Modifies this {@code BitMatrix} to represent the same but rotated 90 degrees counterclockwise
338	   */
339	  public void rotate90() {
340	    int newWidth = height;
341	    int newHeight = width;
342	    int newRowSize = (newWidth + 31) / 32;
343	    int[] newBits = new int[newRowSize * newHeight];
344	
345	    for (int y = 0; y < height; y++) {
346	      for (int x = 0; x < width; x++) {
347	        int offset = y * rowSize + (x / 32);
348	        if (((bits[offset] >>> (x & 0x1f)) & 1) != 0) {
349	          int newOffset = (newHeight - 1 - x) * newRowSize + (y / 32);
350	          newBits[newOffset] |= 1 << (y & 0x1f);
351	        }
352	      }
353	    }
354	    width = newWidth;
355	    height = newHeight;
356	    rowSize = newRowSize;
357	    bits = newBits;
358	  }
