360	  /**
361	   * This is useful in detecting the enclosing rectangle of a 'pure' barcode.
362	   *
363	   * @return {@code left,top,width,height} enclosing rectangle of all 1 bits, or null if it is all white
364	   */
365	  public int[] getEnclosingRectangle() {
366	    int left = width;
367	    int top = height;
368	    int right = -1;
369	    int bottom = -1;
370	
371	    for (int y = 0; y < height; y++) {
372	      for (int x32 = 0; x32 < rowSize; x32++) {
373	        int theBits = bits[y * rowSize + x32];
374	        if (theBits != 0) {
375	          if (y < top) {
376	            top = y;
377	          }
378	          if (y > bottom) {
379	            bottom = y;
380	          }
381	          if (x32 * 32 < left) {
382	            int bit = 0;
383	            while ((theBits << (31 - bit)) == 0) {
384	              bit++;
385	            }
386	            if ((x32 * 32 + bit) < left) {
387	              left = x32 * 32 + bit;
388	            }
389	          }
390	          if (x32 * 32 + 31 > right) {
391	            int bit = 31;
392	            while ((theBits >>> bit) == 0) {
393	              bit--;
394	            }
395	            if ((x32 * 32 + bit) > right) {
396	              right = x32 * 32 + bit;
397	            }
398	          }
399	        }
400	      }
401	    }
402	
403	    if (right < left || bottom < top) {
404	      return null;
405	    }
406	
407	    return new int[] {left, top, right - left + 1, bottom - top + 1};
408	  }
