410	  /**
411	   * This is useful in detecting a corner of a 'pure' barcode.
412	   *
413	   * @return {@code x,y} coordinate of top-left-most 1 bit, or null if it is all white
414	   */
415	  public int[] getTopLeftOnBit() {
416	    int bitsOffset = 0;
417	    while (bitsOffset < bits.length && bits[bitsOffset] == 0) {
418	      bitsOffset++;
419	    }
420	    if (bitsOffset == bits.length) {
421	      return null;
422	    }
423	    int y = bitsOffset / rowSize;
424	    int x = (bitsOffset % rowSize) * 32;
425	
426	    int theBits = bits[bitsOffset];
427	    int bit = 0;
428	    while ((theBits << (31 - bit)) == 0) {
429	      bit++;
430	    }
431	    x += bit;
432	    return new int[] {x, y};
433	  }
434	
435	  public int[] getBottomRightOnBit() {
436	    int bitsOffset = bits.length - 1;
437	    while (bitsOffset >= 0 && bits[bitsOffset] == 0) {
438	      bitsOffset--;
439	    }
440	    if (bitsOffset < 0) {
441	      return null;
442	    }
443	
444	    int y = bitsOffset / rowSize;
445	    int x = (bitsOffset % rowSize) * 32;
446	
447	    int theBits = bits[bitsOffset];
448	    int bit = 31;
449	    while ((theBits >>> bit) == 0) {
450	      bit--;
451	    }
452	    x += bit;
453	
454	    return new int[] {x, y};
455	  }
