58	  // The mask penalty calculation is complicated.  See Table 21 of JISX0510:2004 (p.45) for details.
59	  // Basically it applies four rules and summate all penalties.
60	  private static int calculateMaskPenalty(ByteMatrix matrix) {
61	    return MaskUtil.applyMaskPenaltyRule1(matrix)
62	        + MaskUtil.applyMaskPenaltyRule2(matrix)
63	        + MaskUtil.applyMaskPenaltyRule3(matrix)
64	        + MaskUtil.applyMaskPenaltyRule4(matrix);
65	  }
