67	  /**
68	   * @param content text to encode
69	   * @param ecLevel error correction level to use
70	   * @return {@link QRCode} representing the encoded QR code
71	   * @throws WriterException if encoding can't succeed, because of for example invalid content
72	   *   or configuration
73	   */
74	  public static QRCode encode(String content, ErrorCorrectionLevel ecLevel) throws WriterException {
75	    return encode(content, ecLevel, null);
76	  }
