78	  public static QRCode encode(String content,
79	                              ErrorCorrectionLevel ecLevel,
80	                              Map<EncodeHintType,?> hints) throws WriterException {
81	
82	    Version version;
83	    BitArray headerAndDataBits;
84	    Mode mode;
85	
86	    boolean hasGS1FormatHint = hints != null && hints.containsKey(EncodeHintType.GS1_FORMAT) &&
87	        Boolean.parseBoolean(hints.get(EncodeHintType.GS1_FORMAT).toString());
88	    boolean hasCompactionHint = hints != null && hints.containsKey(EncodeHintType.QR_COMPACT) &&
89	        Boolean.parseBoolean(hints.get(EncodeHintType.QR_COMPACT).toString());
90	
91	    // Determine what character encoding has been specified by the caller, if any
92	    Charset encoding = DEFAULT_BYTE_MODE_ENCODING;
93	    boolean hasEncodingHint = hints != null && hints.containsKey(EncodeHintType.CHARACTER_SET);
94	    if (hasEncodingHint) {
95	      try {
96	        encoding = Charset.forName(hints.get(EncodeHintType.CHARACTER_SET).toString());
97	      } catch (UnsupportedCharsetException ignore) {
98	        //ignore the encodingHint and use the DEFAULT_BYTE_MODE_ENCODING
99	      }
100	    }

100	    }
101	
102	    if (hasCompactionHint) {
103	      mode = Mode.BYTE;
104	
105	      Charset priorityEncoding = encoding.equals(DEFAULT_BYTE_MODE_ENCODING) ? null : encoding;
106	      MinimalEncoder.ResultList rn = MinimalEncoder.encode(content, null, priorityEncoding, hasGS1FormatHint, ecLevel);
107	
108	      headerAndDataBits = new BitArray();
109	      rn.getBits(headerAndDataBits);
110	      version = rn.getVersion();
111	
112	    } else {
113	
114	      // Pick an encoding mode appropriate for the content. Note that this will not attempt to use
115	      // multiple modes / segments even if that were more efficient.
116	      mode = chooseMode(content, encoding);
117	
118	      // This will store the header information, like mode and
119	      // length, as well as "header" segments like an ECI segment.
120	      BitArray headerBits = new BitArray();
121	
122	      // Append ECI segment if applicable
123	      if (mode == Mode.BYTE && hasEncodingHint) {
124	        CharacterSetECI eci = CharacterSetECI.getCharacterSetECI(encoding);
125	        if (eci != null) {
126	          appendECI(eci, headerBits);
127	        }
128	      }
129	
130	      // Append the FNC1 mode header for GS1 formatted data if applicable
131	      if (hasGS1FormatHint) {
132	        // GS1 formatted codes are prefixed with a FNC1 in first position mode header
133	        appendModeInfo(Mode.FNC1_FIRST_POSITION, headerBits);
134	      }
135	
136	      // (With ECI in place,) Write the mode marker
137	      appendModeInfo(mode, headerBits);
138	
139	      // Collect data within the main segment, separately, to count its size if needed. Don't add it to
140	      // main payload yet.
141	      BitArray dataBits = new BitArray();
142	      appendBytes(content, mode, dataBits, encoding);
143	
144	      if (hints != null && hints.containsKey(EncodeHintType.QR_VERSION)) {
145	        int versionNumber = Integer.parseInt(hints.get(EncodeHintType.QR_VERSION).toString());
146	        version = Version.getVersionForNumber(versionNumber);
147	        int bitsNeeded = calculateBitsNeeded(mode, headerBits, dataBits, version);
148	        if (!willFit(bitsNeeded, version, ecLevel)) {
149	          throw new WriterException("Data too big for requested version");
150	        }
151	      } else {
152	        version = recommendVersion(ecLevel, mode, headerBits, dataBits);
153	      }
154	
155	      headerAndDataBits = new BitArray();
156	      headerAndDataBits.appendBitArray(headerBits);
157	      // Find "length" of main segment and write it
158	      int numLetters = mode == Mode.BYTE ? dataBits.getSizeInBytes() : content.length();
159	      appendLengthInfo(numLetters, version, mode, headerAndDataBits);
160	      // Put data together into the overall payload
161	      headerAndDataBits.appendBitArray(dataBits);
162	    }
163	
164	    Version.ECBlocks ecBlocks = version.getECBlocksForLevel(ecLevel);
165	    int numDataBytes = version.getTotalCodewords() - ecBlocks.getTotalECCodewords();
166	
167	    // Terminate the bits properly.
168	    terminateBits(numDataBytes, headerAndDataBits);
169	
170	    // Interleave data bits with error correction code.
171	    BitArray finalBits = interleaveWithECBytes(headerAndDataBits,
172	                                               version.getTotalCodewords(),
173	                                               numDataBytes,
174	                                               ecBlocks.getNumBlocks());
175	
176	    QRCode qrCode = new QRCode();
177	
178	    qrCode.setECLevel(ecLevel);
179	    qrCode.setMode(mode);
180	    qrCode.setVersion(version);
181	
182	    //  Choose the mask pattern and set to "qrCode".
183	    int dimension = version.getDimensionForVersion();
184	    ByteMatrix matrix = new ByteMatrix(dimension, dimension);
185	
186	    // Enable manual selection of the pattern to be used via hint
187	    int maskPattern = -1;
188	    if (hints != null && hints.containsKey(EncodeHintType.QR_MASK_PATTERN)) {
189	      int hintMaskPattern = Integer.parseInt(hints.get(EncodeHintType.QR_MASK_PATTERN).toString());
190	      maskPattern = QRCode.isValidMaskPattern(hintMaskPattern) ? hintMaskPattern : -1;
191	    }
192	
193	    if (maskPattern == -1) {
194	      maskPattern = chooseMaskPattern(finalBits, ecLevel, version, matrix);
195	    }
196	    qrCode.setMaskPattern(maskPattern);
197	
198	    // Build the matrix and set it to "qrCode".
199	    MatrixUtil.buildMatrix(finalBits, ecLevel, version, maskPattern, matrix);
200	    qrCode.setMatrix(matrix);
201	
202	    return qrCode;
203	  }
