205	  /**
206	   * Decides the smallest version of QR code that will contain all of the provided data.
207	   *
208	   * @throws WriterException if the data cannot fit in any version
209	   */
210	  private static Version recommendVersion(ErrorCorrectionLevel ecLevel,
211	                                          Mode mode,
212	                                          BitArray headerBits,
213	                                          BitArray dataBits) throws WriterException {
214	    // Hard part: need to know version to know how many bits length takes. But need to know how many
215	    // bits it takes to know version. First we take a guess at version by assuming version will be
216	    // the minimum, 1:
217	    int provisionalBitsNeeded = calculateBitsNeeded(mode, headerBits, dataBits, Version.getVersionForNumber(1));
218	    Version provisionalVersion = chooseVersion(provisionalBitsNeeded, ecLevel);
219	
220	    // Use that guess to calculate the right version. I am still not sure this works in 100% of cases.
221	    int bitsNeeded = calculateBitsNeeded(mode, headerBits, dataBits, provisionalVersion);
222	    return chooseVersion(bitsNeeded, ecLevel);
223	  }
224	
225	  private static int calculateBitsNeeded(Mode mode,
226	                                         BitArray headerBits,
227	                                         BitArray dataBits,
228	                                         Version version) {
229	    return headerBits.getSize() + mode.getCharacterCountBits(version) + dataBits.getSize();
230	  }
