232	  /**
233	   * @return the code point of the table used in alphanumeric mode or
234	   *  -1 if there is no corresponding code in the table.
235	   */
236	  static int getAlphanumericCode(int code) {
237	    if (code < ALPHANUMERIC_TABLE.length) {
238	      return ALPHANUMERIC_TABLE[code];
239	    }
240	    return -1;
241	  }
