325	  /**
326	   * @return true if the number of input bits will fit in a code with the specified version and
327	   * error correction level.
328	   */
329	  static boolean willFit(int numInputBits, Version version, ErrorCorrectionLevel ecLevel) {
330	    // In the following comments, we use numbers of Version 7-H.
331	    // numBytes = 196
332	    int numBytes = version.getTotalCodewords();
333	    // getNumECBytes = 130
334	    Version.ECBlocks ecBlocks = version.getECBlocksForLevel(ecLevel);
335	    int numEcBytes = ecBlocks.getTotalECCodewords();
336	    // getNumDataBytes = 196 - 130 = 66
337	    int numDataBytes = numBytes - numEcBytes;
338	    int totalInputBytes = (numInputBits + 7) / 8;
339	    return numDataBytes >= totalInputBytes;
340	  }
