343	   * Terminate bits as described in 8.4.8 and 8.4.9 of JISX0510:2004 (p.24).
344	   */
345	  static void terminateBits(int numDataBytes, BitArray bits) throws WriterException {
346	    int capacity = numDataBytes * 8;
347	    if (bits.getSize() > capacity) {
348	      throw new WriterException("data bits cannot fit in the QR Code" + bits.getSize() + " > " +
349	          capacity);

345	  static void terminateBits(int numDataBytes, BitArray bits) throws WriterException {
346	    int capacity = numDataBytes * 8;
347	    if (bits.getSize() > capacity) {
348	      throw new WriterException("data bits cannot fit in the QR Code" + bits.getSize() + " > " +
349	          capacity);
350	    }
351	    // Append Mode.TERMINATE if there is enough space (value is 0000)
352	    for (int i = 0; i < 4 && bits.getSize() < capacity; ++i) {
353	      bits.appendBit(false);
354	    }
355	    // Append termination bits. See 8.4.8 of JISX0510:2004 (p.24) for details.
356	    // If the last byte isn't 8-bit aligned, we'll add padding bits.
357	    int numBitsInLastByte = bits.getSize() & 0x07;
358	    if (numBitsInLastByte > 0) {
359	      for (int i = numBitsInLastByte; i < 8; i++) {
360	        bits.appendBit(false);
361	      }
362	    }
363	    // If we have more space, we'll fill the space with padding patterns defined in 8.4.9 (p.24).
364	    int numPaddingBytes = numDataBytes - bits.getSizeInBytes();
365	    for (int i = 0; i < numPaddingBytes; ++i) {
366	      bits.appendBits((i & 0x01) == 0 ? 0xEC : 0x11, 8);
367	    }
368	    if (bits.getSize() != capacity) {
369	      throw new WriterException("Bits size does not equal capacity");
370	    }
371	  }
