373	  /**
374	   * Get number of data bytes and number of error correction bytes for block id "blockID". Store
375	   * the result in "numDataBytesInBlock", and "numECBytesInBlock". See table 12 in 8.5.1 of
376	   * JISX0510:2004 (p.30)
377	   */
378	  static void getNumDataBytesAndNumECBytesForBlockID(int numTotalBytes,
379	                                                     int numDataBytes,
380	                                                     int numRSBlocks,
381	                                                     int blockID,
382	                                                     int[] numDataBytesInBlock,
383	                                                     int[] numECBytesInBlock) throws WriterException {
384	    if (blockID >= numRSBlocks) {
385	      throw new WriterException("Block ID too large");
386	    }
387	    // numRsBlocksInGroup2 = 196 % 5 = 1
388	    int numRsBlocksInGroup2 = numTotalBytes % numRSBlocks;
389	    // numRsBlocksInGroup1 = 5 - 1 = 4
390	    int numRsBlocksInGroup1 = numRSBlocks - numRsBlocksInGroup2;
391	    // numTotalBytesInGroup1 = 196 / 5 = 39
392	    int numTotalBytesInGroup1 = numTotalBytes / numRSBlocks;
393	    // numTotalBytesInGroup2 = 39 + 1 = 40
394	    int numTotalBytesInGroup2 = numTotalBytesInGroup1 + 1;
395	    // numDataBytesInGroup1 = 66 / 5 = 13
396	    int numDataBytesInGroup1 = numDataBytes / numRSBlocks;
397	    // numDataBytesInGroup2 = 13 + 1 = 14
398	    int numDataBytesInGroup2 = numDataBytesInGroup1 + 1;
399	    // numEcBytesInGroup1 = 39 - 13 = 26
400	    int numEcBytesInGroup1 = numTotalBytesInGroup1 - numDataBytesInGroup1;
401	    // numEcBytesInGroup2 = 40 - 14 = 26
402	    int numEcBytesInGroup2 = numTotalBytesInGroup2 - numDataBytesInGroup2;
403	    // Sanity checks.
404	    // 26 = 26
405	    if (numEcBytesInGroup1 != numEcBytesInGroup2) {
406	      throw new WriterException("EC bytes mismatch");
407	    }
408	    // 5 = 4 + 1.
409	    if (numRSBlocks != numRsBlocksInGroup1 + numRsBlocksInGroup2) {
410	      throw new WriterException("RS blocks mismatch");
411	    }
412	    // 196 = (13 + 26) * 4 + (14 + 26) * 1
413	    if (numTotalBytes !=
414	        ((numDataBytesInGroup1 + numEcBytesInGroup1) *
415	            numRsBlocksInGroup1) +
416	            ((numDataBytesInGroup2 + numEcBytesInGroup2) *
417	                numRsBlocksInGroup2)) {
418	      throw new WriterException("Total bytes mismatch");
419	    }
420	
421	    if (blockID < numRsBlocksInGroup1) {
422	      numDataBytesInBlock[0] = numDataBytesInGroup1;
423	      numECBytesInBlock[0] = numEcBytesInGroup1;
424	    } else {
425	      numDataBytesInBlock[0] = numDataBytesInGroup2;
426	      numECBytesInBlock[0] = numEcBytesInGroup2;
427	    }
428	  }
