430	  /**
431	   * Interleave "bits" with corresponding error correction bytes. On success, store the result in
432	   * "result". The interleave rule is complicated. See 8.6 of JISX0510:2004 (p.37) for details.
433	   */
434	  static BitArray interleaveWithECBytes(BitArray bits,
435	                                        int numTotalBytes,
436	                                        int numDataBytes,
437	                                        int numRSBlocks) throws WriterException {
438	
439	    // "bits" must have "getNumDataBytes" bytes of data.
440	    if (bits.getSizeInBytes() != numDataBytes) {
441	      throw new WriterException("Number of bits and data bytes does not match");
442	    }
443	
444	    // Step 1.  Divide data bytes into blocks and generate error correction bytes for them. We'll
445	    // store the divided data bytes blocks and error correction bytes blocks into "blocks".
446	    int dataBytesOffset = 0;
447	    int maxNumDataBytes = 0;
448	    int maxNumEcBytes = 0;
449	
450	    // Since, we know the number of reedsolmon blocks, we can initialize the vector with the number.
451	    Collection<BlockPair> blocks = new ArrayList<>(numRSBlocks);
452	
453	    for (int i = 0; i < numRSBlocks; ++i) {
454	      int[] numDataBytesInBlock = new int[1];
455	      int[] numEcBytesInBlock = new int[1];
456	      getNumDataBytesAndNumECBytesForBlockID(
457	          numTotalBytes, numDataBytes, numRSBlocks, i,
458	          numDataBytesInBlock, numEcBytesInBlock);
459	
460	      int size = numDataBytesInBlock[0];
461	      byte[] dataBytes = new byte[size];
462	      bits.toBytes(8 * dataBytesOffset, dataBytes, 0, size);
463	      byte[] ecBytes = generateECBytes(dataBytes, numEcBytesInBlock[0]);
464	      blocks.add(new BlockPair(dataBytes, ecBytes));
465	
466	      maxNumDataBytes = Math.max(maxNumDataBytes, size);
467	      maxNumEcBytes = Math.max(maxNumEcBytes, ecBytes.length);
468	      dataBytesOffset += numDataBytesInBlock[0];
469	    }
470	    if (numDataBytes != dataBytesOffset) {
471	      throw new WriterException("Data bytes does not match offset");
472	    }
473	
474	    BitArray result = new BitArray();
475	
476	    // First, place data blocks.
477	    for (int i = 0; i < maxNumDataBytes; ++i) {
478	      for (BlockPair block : blocks) {
479	        byte[] dataBytes = block.getDataBytes();
480	        if (i < dataBytes.length) {
481	          result.appendBits(dataBytes[i], 8);
482	        }
483	      }
484	    }
485	    // Then, place error correction blocks.
486	    for (int i = 0; i < maxNumEcBytes; ++i) {
487	      for (BlockPair block : blocks) {
488	        byte[] ecBytes = block.getErrorCorrectionBytes();
489	        if (i < ecBytes.length) {
490	          result.appendBits(ecBytes[i], 8);
491	        }
492	      }
493	    }
494	    if (numTotalBytes != result.getSizeInBytes()) {  // Should be same.
495	      throw new WriterException("Interleaving error: " + numTotalBytes + " and " +
496	          result.getSizeInBytes() + " differ.");
497	    }
498	
499	    return result;
500	  }
501	
502	  static byte[] generateECBytes(byte[] dataBytes, int numEcBytesInBlock) {
503	    int numDataBytes = dataBytes.length;
504	    int[] toEncode = new int[numDataBytes + numEcBytesInBlock];
505	    for (int i = 0; i < numDataBytes; i++) {
506	      toEncode[i] = dataBytes[i] & 0xFF;
507	    }
508	    new ReedSolomonEncoder(GenericGF.QR_CODE_FIELD_256).encode(toEncode, numEcBytesInBlock);
509	
510	    byte[] ecBytes = new byte[numEcBytesInBlock];
511	    for (int i = 0; i < numEcBytesInBlock; i++) {
512	      ecBytes[i] = (byte) toEncode[numDataBytes + i];
513	    }
514	    return ecBytes;
515	  }
