561	  static void appendNumericBytes(CharSequence content, BitArray bits) {
562	    int length = content.length();
563	    int i = 0;
564	    while (i < length) {
565	      int num1 = content.charAt(i) - '0';
566	      if (i + 2 < length) {
567	        // Encode three numeric letters in ten bits.
568	        int num2 = content.charAt(i + 1) - '0';
569	        int num3 = content.charAt(i + 2) - '0';
570	        bits.appendBits(num1 * 100 + num2 * 10 + num3, 10);
571	        i += 3;
572	      } else if (i + 1 < length) {
573	        // Encode two numeric letters in seven bits.
574	        int num2 = content.charAt(i + 1) - '0';
575	        bits.appendBits(num1 * 10 + num2, 7);
576	        i += 2;
577	      } else {
578	        // Encode one numeric letter in four bits.
579	        bits.appendBits(num1, 4);
580	        i++;
581	      }
582	    }
583	  }
