585	  static void appendAlphanumericBytes(CharSequence content, BitArray bits) throws WriterException {
586	    int length = content.length();
587	    int i = 0;
588	    while (i < length) {
589	      int code1 = getAlphanumericCode(content.charAt(i));
590	      if (code1 == -1) {
591	        throw new WriterException();
592	      }
593	      if (i + 1 < length) {
594	        int code2 = getAlphanumericCode(content.charAt(i + 1));
595	        if (code2 == -1) {
596	          throw new WriterException();
597	        }
598	        // Encode two alphanumeric letters in 11 bits.
599	        bits.appendBits(code1 * 45 + code2, 11);
600	        i += 2;
601	      } else {
602	        // Encode one alphanumeric letter in six bits.
603	        bits.appendBits(code1, 6);
604	        i++;
605	      }
606	    }
607	  }
