616	  static void appendKanjiBytes(String content, BitArray bits) throws WriterException {
617	    if (StringUtils.SHIFT_JIS_CHARSET == null) {
618	      // Not supported without charset support
619	      throw new WriterException("SJIS Charset not supported on this platform");
620	    }
621	    byte[] bytes = content.getBytes(StringUtils.SHIFT_JIS_CHARSET);
622	    if (bytes.length % 2 != 0) {
623	      throw new WriterException("Kanji byte size not even");
624	    }
625	    int maxI = bytes.length - 1; // bytes.length must be even
626	    for (int i = 0; i < maxI; i += 2) {
627	      int byte1 = bytes[i] & 0xFF;
628	      int byte2 = bytes[i + 1] & 0xFF;
629	      int code = (byte1 << 8) | byte2;
630	      int subtracted = -1;
631	      if (code >= 0x8140 && code <= 0x9ffc) {
632	        subtracted = code - 0x8140;
633	      } else if (code >= 0xe040 && code <= 0xebbf) {
634	        subtracted = code - 0xc140;
635	      }
636	      if (subtracted == -1) {
637	        throw new WriterException("Invalid byte sequence");
638	      }
639	      int encoded = ((subtracted >> 8) * 0xc0) + (subtracted & 0xff);
640	      bits.appendBits(encoded, 13);
641	    }
642	  }

