131	  /**
132	   * Performs message encoding of a DataMatrix message using the algorithm described in annex P
133	   * of ISO/IEC 16022:2000(E).
134	   *
135	   * @param msg     the message
136	   * @param shape   requested shape. May be {@code SymbolShapeHint.FORCE_NONE},
137	   *                {@code SymbolShapeHint.FORCE_SQUARE} or {@code SymbolShapeHint.FORCE_RECTANGLE}.
138	   * @param minSize the minimum symbol size constraint or null for no constraint
139	   * @param maxSize the maximum symbol size constraint or null for no constraint
140	   * @return the encoded message (the char values range from 0 to 255)
141	   */
142	  public static String encodeHighLevel(String msg,
143	                                       SymbolShapeHint shape,
144	                                       Dimension minSize,
145	                                       Dimension maxSize) {
146	    return encodeHighLevel(msg, shape, minSize, maxSize, false);
147	  }
148	  /**
149	   * Performs message encoding of a DataMatrix message using the algorithm described in annex P
150	   * of ISO/IEC 16022:2000(E).
151	   *
152	   * @param msg     the message
153	   * @param shape   requested shape. May be {@code SymbolShapeHint.FORCE_NONE},
154	   *                {@code SymbolShapeHint.FORCE_SQUARE} or {@code SymbolShapeHint.FORCE_RECTANGLE}.
155	   * @param minSize the minimum symbol size constraint or null for no constraint
156	   * @param maxSize the maximum symbol size constraint or null for no constraint
157	   * @param forceC40 enforce C40 encoding
158	   * @return the encoded message (the char values range from 0 to 255)
159	   */
160	  public static String encodeHighLevel(String msg,
161	                                       SymbolShapeHint shape,
162	                                       Dimension minSize,
163	                                       Dimension maxSize,
164	                                       boolean forceC40) {
165	    //the codewords 0..255 are encoded as Unicode characters
166	    C40Encoder c40Encoder = new C40Encoder();
167	    Encoder[] encoders = {
168	        new ASCIIEncoder(), c40Encoder, new TextEncoder(),
169	        new X12Encoder(), new EdifactEncoder(),  new Base256Encoder()
170	    };
171	
172	    EncoderContext context = new EncoderContext(msg);
173	    context.setSymbolShape(shape);
174	    context.setSizeConstraints(minSize, maxSize);
175	
176	    if (msg.startsWith(MACRO_05_HEADER) && msg.endsWith(MACRO_TRAILER)) {
177	      context.writeCodeword(MACRO_05);
178	      context.setSkipAtEnd(2);
179	      context.pos += MACRO_05_HEADER.length();
180	    } else if (msg.startsWith(MACRO_06_HEADER) && msg.endsWith(MACRO_TRAILER)) {
181	      context.writeCodeword(MACRO_06);
182	      context.setSkipAtEnd(2);
183	      context.pos += MACRO_06_HEADER.length();
184	    }
185	
186	    int encodingMode = ASCII_ENCODATION; //Default mode
187	
188	    if (forceC40) {
189	      c40Encoder.encodeMaximal(context);
190	      encodingMode = context.getNewEncoding();
191	      context.resetEncoderSignal();
192	    }
193	
194	    while (context.hasMoreCharacters()) {
195	      encoders[encodingMode].encode(context);
196	      if (context.getNewEncoding() >= 0) {
197	        encodingMode = context.getNewEncoding();
198	        context.resetEncoderSignal();
199	      }
200	    }
201	    int len = context.getCodewordCount();
202	    context.updateSymbolInfo();
203	    int capacity = context.getSymbolInfo().getDataCapacity();
204	    if (len < capacity &&
205	        encodingMode != ASCII_ENCODATION &&
206	        encodingMode != BASE256_ENCODATION &&
207	        encodingMode != EDIFACT_ENCODATION) {
208	      context.writeCodeword('\u00fe'); //Unlatch (254)
209	    }
210	    //Padding
211	    StringBuilder codewords = context.getCodewords();
212	    if (codewords.length() < capacity) {
213	      codewords.append(PAD);
214	    }
215	    while (codewords.length() < capacity) {
216	      codewords.append(randomize253State(codewords.length() + 1));
217	    }
218	
219	    return context.getCodewords().toString();
220	  }
