222	  static int lookAheadTest(CharSequence msg, int startpos, int currentMode) {
223	    int newMode = lookAheadTestIntern(msg, startpos, currentMode);
224	    if (currentMode == X12_ENCODATION && newMode == X12_ENCODATION) {
225	      int endpos = Math.min(startpos + 3, msg.length());
226	      for (int i = startpos; i < endpos; i++) {
227	        if (!isNativeX12(msg.charAt(i))) {
228	          return ASCII_ENCODATION;
229	        }
230	      }
231	    } else if (currentMode == EDIFACT_ENCODATION && newMode == EDIFACT_ENCODATION) {
232	      int endpos = Math.min(startpos + 4, msg.length());
233	      for (int i = startpos; i < endpos; i++) {
234	        if (!isNativeEDIFACT(msg.charAt(i))) {
235	          return ASCII_ENCODATION;
236	        }
237	      }
238	    }
239	    return newMode;
240	  }
