242	  static int lookAheadTestIntern(CharSequence msg, int startpos, int currentMode) {
243	    if (startpos >= msg.length()) {
244	      return currentMode;
245	    }
246	    float[] charCounts;
247	    //step J
248	    if (currentMode == ASCII_ENCODATION) {
249	      charCounts = new float[]{0, 1, 1, 1, 1, 1.25f};
250	    } else {
251	      charCounts = new float[]{1, 2, 2, 2, 2, 2.25f};
252	      charCounts[currentMode] = 0;
253	    }
254	
255	    int charsProcessed = 0;
256	    byte[] mins = new byte[6];
257	    int[] intCharCounts = new int[6];
258	    while (true) {
259	      //step K
260	      if ((startpos + charsProcessed) == msg.length()) {
261	        Arrays.fill(mins, (byte) 0);
262	        Arrays.fill(intCharCounts, 0);
263	        int min = findMinimums(charCounts, intCharCounts, Integer.MAX_VALUE, mins);
264	        int minCount = getMinimumCount(mins);
265	
266	        if (intCharCounts[ASCII_ENCODATION] == min) {
267	          return ASCII_ENCODATION;
268	        }
269	        if (minCount == 1) {
270	          if (mins[BASE256_ENCODATION] > 0) {
271	            return BASE256_ENCODATION;
272	          }
273	          if (mins[EDIFACT_ENCODATION] > 0) {
274	            return EDIFACT_ENCODATION;
275	          }
276	          if (mins[TEXT_ENCODATION] > 0) {
277	            return TEXT_ENCODATION;
278	          }
279	          if (mins[X12_ENCODATION] > 0) {
280	            return X12_ENCODATION;
281	          }
282	        }
283	        return C40_ENCODATION;
284	      }
285	
286	      char c = msg.charAt(startpos + charsProcessed);
287	      charsProcessed++;
288	
289	      //step L
290	      if (isDigit(c)) {
291	        charCounts[ASCII_ENCODATION] += 0.5f;
292	      } else if (isExtendedASCII(c)) {
293	        charCounts[ASCII_ENCODATION] = (float) Math.ceil(charCounts[ASCII_ENCODATION]);
294	        charCounts[ASCII_ENCODATION] += 2.0f;
295	      } else {
296	        charCounts[ASCII_ENCODATION] = (float) Math.ceil(charCounts[ASCII_ENCODATION]);
297	        charCounts[ASCII_ENCODATION]++;
298	      }
299	
300	      //step M
301	      if (isNativeC40(c)) {
302	        charCounts[C40_ENCODATION] += 2.0f / 3.0f;
303	      } else if (isExtendedASCII(c)) {
